css:
.sl-gallery-chapters { padding: 5rem 0; background-color: var(--smartlearn-bg); }
.sl-gallery-chapters .sl-mb-16 { margin-bottom: 3rem; }
.sl-gallery-chapters .sl-section-title { font-size: 2.25rem; font-weight: 700; color: var(--smartlearn-text); margin-bottom: 0.5rem; }
.sl-gallery-chapters .sl-section-subtitle { font-size: 1.125rem; color: var(--smartlearn-text-muted); }
.sl-gallery-chapters .sl-chapters-layout { display: flex; flex-direction: column; gap: 2rem; }
@media (min-width: 992px) { .sl-chapters-layout { flex-direction: row; align-items: stretch; } }
.sl-gallery-chapters .sl-chapters-media { flex: 1; border-radius: 1rem; overflow: hidden; background-color: var(--smartlearn-card-bg); border: 1px solid var(--smartlearn-card-border, rgba(0,0,0,0.05)); }
.sl-gallery-chapters .sl-media-ratio { position: relative; padding-bottom: 56.25%; height: 0; }
.sl-gallery-chapters .sl-chapters-poster { position: absolute; top: 0; left: 0; width: 100%; height: 100%; object-fit: cover; transition: opacity 0.3s ease; }
.sl-gallery-chapters .sl-play-overlay { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 80px; height: 80px; background: #fff; border-radius: 50%; display: flex; align-items: center; justify-content: center; box-shadow: 0 10px 25px rgba(0,0,0,0.2); cursor: pointer; transition: transform 0.2s ease; }
.sl-gallery-chapters .sl-play-overlay:hover { transform: translate(-50%, -50%) scale(1.1); }
.sl-gallery-chapters .sl-chapters-nav { display: flex; flex-direction: row; overflow-x: auto; gap: 1rem; padding-bottom: 1rem; scroll-snap-type: x mandatory; }
@media (min-width: 992px) { .sl-chapters-nav { flex-direction: column; overflow-x: visible; width: 350px; padding-bottom: 0; scroll-snap-type: none; } }
.sl-gallery-chapters .sl-chapter-item { display: flex; align-items: center; gap: 1rem; padding: 1rem; background-color: var(--smartlearn-card-bg); border: 1px solid var(--smartlearn-card-border, rgba(0,0,0,0.05)); border-radius: 0.75rem; text-align: left; cursor: pointer; transition: all 0.2s ease; min-width: 280px; scroll-snap-align: start; outline: none; }
.sl-gallery-chapters .sl-chapter-item:focus-visible { box-shadow: 0 0 0 3px var(--smartlearn-primary); }
.sl-gallery-chapters .sl-chapter-item:hover { background-color: var(--smartlearn-bg); }
.sl-gallery-chapters .sl-chapter-item.sl-active { border-color: var(--smartlearn-primary); background-color: var(--smartlearn-bg); box-shadow: 0 4px 15px rgba(0,0,0,0.05); }
.sl-gallery-chapters .sl-chapter-thumb { width: 80px; height: 60px; border-radius: 0.5rem; overflow: hidden; flex-shrink: 0; }
.sl-gallery-chapters .sl-chapter-thumb img { width: 100%; height: 100%; object-fit: cover; }
.sl-gallery-chapters .sl-chapter-info { display: flex; flex-direction: column; }
.sl-gallery-chapters .sl-chapter-num { font-size: 0.75rem; font-weight: 700; text-transform: uppercase; color: var(--smartlearn-primary); margin-bottom: 0.25rem; }
.sl-gallery-chapters .sl-chapter-title { font-size: 1rem; font-weight: 600; color: var(--smartlearn-text); margin: 0; line-height: 1.4; }

js:
(function() {
    const root = document.querySelector('.sl-gallery-chapters');
    if (!root) return;
    const chapters = root.querySelectorAll('.sl-chapter-item');
    const activeImg = root.querySelector('#sl-chapter-active-img');
    const playBtn = root.querySelector('#sl-chapter-play-btn');
    const mediaArea = root.querySelector('#sl-chapters-media-area');
    if(!chapters.length || !activeImg || !playBtn || !mediaArea) return;

    let currentVideoUrl = "";

    function updateActiveChapter(btn) {
        if(document.body.classList.contains('sl-editor-mode')) return;

        const existingIframe = mediaArea.querySelector('iframe');
        if(existingIframe) existingIframe.remove();

        activeImg.style.display = 'block';
        playBtn.style.display = 'flex';

        chapters.forEach(c => c.classList.remove('sl-active'));
        btn.classList.add('sl-active');

        const poster = btn.getAttribute('data-poster');
        if(poster) activeImg.src = poster;

        const urlEl = btn.querySelector('.sl-chapter-video-url');
        if(urlEl) {
            currentVideoUrl = urlEl.innerText.trim();
        }
    }

    chapters.forEach(btn => {
        btn.addEventListener('click', () => updateActiveChapter(btn));
    });

    playBtn.addEventListener('click', () => {
        if(document.body.classList.contains('sl-editor-mode') || !currentVideoUrl) return;

        activeImg.style.display = 'none';
        playBtn.style.display = 'none';

        const iframe = document.createElement('iframe');
        iframe.src = currentVideoUrl + (currentVideoUrl.includes('?') ? '&' : '?') + 'autoplay=1';
        iframe.style.position = 'absolute';
        iframe.style.top = '0';
        iframe.style.left = '0';
        iframe.style.width = '100%';
        iframe.style.height = '100%';
        iframe.style.border = 'none';
        iframe.setAttribute('allow', 'autoplay; fullscreen; encrypted-media');
        iframe.setAttribute('allowfullscreen', 'true');

        mediaArea.appendChild(iframe);
    });

    // Init first chapter
    const firstActive = root.querySelector('.sl-chapter-item.sl-active') || chapters[0];
    const urlEl = firstActive.querySelector('.sl-chapter-video-url');
    if(urlEl) currentVideoUrl = urlEl.innerText.trim();
})();
